# 🟢 低风险：只读/信息收集，通常无副作用
# 配置仅允许指定仓库的签名镜像，其余仓库默认拒绝
sudo tee /etc/containers/policy.json <<'EOF'
{
  "default": [{"type": "reject"}],
  "transports": {
    "docker": {
      "registry.cn-hangzhou.aliyuncs.com/demo": [
        {"type": "signedBy", "keyType": "GPGKeys", "keyPath": "/etc/pki/demo-pubkey.gpg"}
      ]
    }
  }
}
EOF
sudo systemctl reload crio
